// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 1, 1 ether);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.deposit{value: amount}();
        uint256 balanceBefore = address(c).balance;
        // Call migrateTo as the creator (the deployer is creator)
        vm.prank(address(this));
        address to = address(0xdead);
        c.migrateTo(to);
        assertTrue(address(c).balance == 0 || balanceBefore == 0);
    }
}

